namespace FGP.Api.CapitalFund;

public sealed class CapitalContribution { public long Id { get; set; } public Guid OrganizationId { get; set; } public Guid MemberId { get; set; } public Guid RecordedByUserId { get; set; } public decimal Amount { get; set; } public DateOnly ContributionDate { get; set; } public string? Note { get; set; } public string Status { get; set; } = "posted"; public DateTimeOffset CreatedAt { get; set; } }
public sealed class CapitalGoalProposal { public long Id { get; set; } public Guid OrganizationId { get; set; } public Guid ProposedByMembershipId { get; set; } public decimal NewAmount { get; set; } public string Status { get; set; } = "open"; public DateTimeOffset SubmittedAt { get; set; } public DateTimeOffset? TerminalAt { get; set; } }
public sealed class CapitalGoalElectorate { public long ProposalId { get; set; } public Guid MembershipId { get; set; } }
public sealed class CapitalGoalApproval { public long ProposalId { get; set; } public Guid MembershipId { get; set; } public string ApprovalKind { get; set; } = "IndependentApproval"; public DateTimeOffset ApprovedAt { get; set; } }
public sealed class CapitalCorrectionProposal { public long Id { get; set; } public Guid OrganizationId { get; set; } public long ContributionId { get; set; } public Guid ProposedByMembershipId { get; set; } public string Action { get; set; } = "edit"; public decimal? ProposedAmount { get; set; } public string? ProposedNote { get; set; } public string Status { get; set; } = "open"; public DateTimeOffset SubmittedAt { get; set; } public DateTimeOffset? TerminalAt { get; set; } }
public sealed class CapitalCorrectionApproval { public long ProposalId { get; set; } public Guid ApproverMembershipId { get; set; } public DateTimeOffset ApprovedAt { get; set; } }
